import json
from src.nodes.base import BaseNode
from src.runtime.environment_realization import get_room_shell_builder

class Hou_Mcp_Build_Openings(BaseNode):
    name = "hou_mcp_build_openings"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("environment", "string", widget_type="text", default="western_room")
        self.add_output("openings_json")
        self.add_output("door_count",   "int")
        self.add_output("window_count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        env = (inputs.get("environment") or "").strip() or "western_room"
        try:
            shell = get_room_shell_builder().build(env)
            openings = [e.to_dict() for e in shell.openings]
            door_types = {"door", "swing_door", "sliding_door", "loading_door", "archway", "hangar_opening"}
            win_types  = {"window", "skylight", "porthole", "arrow_slit", "vent"}
            door_count   = sum(1 for e in shell.openings if e.element_type in door_types)
            window_count = sum(1 for e in shell.openings if e.element_type in win_types)
            return {
                "openings_json": json.dumps(openings, sort_keys=True, indent=2),
                "door_count":    door_count,
                "window_count":  window_count,
                "exec_out":      True,
            }
        except Exception as exc:
            self.log_error(f"Opening build failed: {exc}")
            return {"openings_json": "[]", "door_count": 0, "window_count": 0, "exec_out": True}

def register_node():
    return Hou_Mcp_Build_Openings
